:root {
  --red: #ff355e;
  --red-soft: #ff7e97;
  --blue: #2fa9ff;
  --blue-soft: #82d4ff;
  --turn-color: var(--red);
  --turn-soft: var(--red-soft);
  --bg: #03050d;
  --bg-2: #060b18;
  --panel: rgba(7, 14, 29, 0.78);
  --panel-solid: #080f20;
  --stroke: rgba(116, 185, 255, 0.18);
  --stroke-strong: rgba(123, 196, 255, 0.34);
  --text: #e6f0ff;
  --muted: #8095b7;
  --dim: #536787;
  --mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", "Roboto Mono", Menlo, Consolas, monospace;
  --sans: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
}

:root[data-turn="red"] {
  --turn-color: var(--red);
  --turn-soft: var(--red-soft);
}

:root[data-turn="blue"] {
  --turn-color: var(--blue);
  --turn-soft: var(--blue-soft);
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  margin: 0;
}

html {
  background: var(--bg);
}

body {
  overflow: hidden;
  overscroll-behavior: none;
  color: var(--text);
  font-family: var(--sans);
  background:
    radial-gradient(ellipse 60% 50% at 18% 0%, rgba(35, 78, 164, 0.16), transparent 65%),
    radial-gradient(ellipse 55% 55% at 88% 100%, rgba(130, 24, 62, 0.14), transparent 65%),
    var(--bg);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
  color: inherit;
}

button,
canvas {
  -webkit-user-select: none;
  user-select: none;
}

button:focus-visible {
  outline: 2px solid var(--blue-soft);
  outline-offset: 3px;
}

[hidden] {
  display: none !important;
}

.app {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100vh;
  height: 100dvh;
  min-height: 0;
  isolation: isolate;
}

/* ------------------------------------------------------------------ */
/* Top bar                                                             */
/* ------------------------------------------------------------------ */

.topbar {
  position: relative;
  z-index: 5;
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  height: 64px;
  padding:
    max(10px, env(safe-area-inset-top))
    max(18px, env(safe-area-inset-right))
    10px
    max(18px, env(safe-area-inset-left));
}

.topbar::after {
  position: absolute;
  right: 18px;
  bottom: 0;
  left: 18px;
  height: 1px;
  content: "";
  background: linear-gradient(90deg, transparent, rgba(105, 178, 255, 0.16) 18%, rgba(105, 178, 255, 0.16) 82%, transparent);
}

.topbar-side {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.topbar-right {
  justify-content: flex-end;
}

.ghost-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 38px;
  padding: 8px 13px;
  color: #9eb2d2;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.16em;
  cursor: pointer;
  background: rgba(9, 18, 36, 0.66);
  border: 1px solid rgba(114, 178, 255, 0.14);
  border-radius: 9px;
  transition: color 160ms ease, border-color 160ms ease, background 160ms ease, transform 120ms ease;
}

.ghost-btn:hover {
  color: #e4f1ff;
  background: rgba(18, 36, 66, 0.78);
  border-color: rgba(114, 178, 255, 0.34);
}

.ghost-btn:active {
  transform: translateY(1px);
}

.ghost-btn.compact {
  width: 38px;
  padding: 0;
}

.ghost-btn .glyph {
  font-size: 15px;
  line-height: 1;
}

.brand {
  margin-left: 6px;
  font-family: var(--mono);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.2em;
  white-space: nowrap;
}

.brand span {
  margin-left: 4px;
  color: var(--dim);
}

.turn-pill {
  display: flex;
  flex: none;
  align-items: center;
  gap: 9px;
  min-height: 36px;
  padding: 7px 17px;
  color: var(--turn-soft);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  white-space: nowrap;
  background: rgba(8, 16, 32, 0.8);
  border: 1px solid color-mix(in srgb, var(--turn-color) 34%, transparent);
  border-radius: 999px;
  box-shadow:
    0 0 26px color-mix(in srgb, var(--turn-color) 11%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
  transition: color 220ms ease, border-color 220ms ease, box-shadow 220ms ease;
}

.turn-dot {
  position: relative;
  width: 8px;
  height: 8px;
  background: var(--turn-color);
  border-radius: 50%;
  box-shadow: 0 0 10px var(--turn-color), 0 0 20px color-mix(in srgb, var(--turn-color) 55%, transparent);
}

.turn-dot::after {
  position: absolute;
  inset: -4px;
  content: "";
  border: 1px solid color-mix(in srgb, var(--turn-color) 55%, transparent);
  border-radius: 50%;
  animation: dotPulse 1.6s ease-out infinite;
}

@keyframes dotPulse {
  0% { opacity: 0.8; transform: scale(0.55); }
  80%, 100% { opacity: 0; transform: scale(1.7); }
}

/* ------------------------------------------------------------------ */
/* Layout                                                              */
/* ------------------------------------------------------------------ */

.game-shell {
  display: grid;
  flex: 1;
  grid-template-columns: minmax(0, 1fr) 292px;
  gap: 16px;
  width: 100%;
  max-width: 1480px;
  min-height: 0;
  margin: 0 auto;
  padding: 14px 18px 18px;
}

.board-stage {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background:
    radial-gradient(ellipse 75% 70% at 50% 46%, rgba(15, 37, 74, 0.34), transparent 72%),
    rgba(4, 8, 18, 0.45);
  border: 1px solid rgba(108, 174, 255, 0.1);
  border-radius: 22px;
  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.35);
}

#gameCanvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

.toast {
  position: absolute;
  bottom: 18px;
  left: 50%;
  padding: 9px 16px;
  color: #d8e9ff;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.14em;
  white-space: nowrap;
  pointer-events: none;
  background: rgba(8, 17, 35, 0.92);
  border: 1px solid rgba(121, 190, 255, 0.26);
  border-radius: 999px;
  opacity: 0;
  transform: translate(-50%, 8px);
  transition: opacity 220ms ease, transform 220ms ease;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

.toast.danger {
  border-color: rgba(255, 62, 96, 0.46);
  box-shadow: 0 0 24px rgba(255, 54, 90, 0.18);
}

/* ------------------------------------------------------------------ */
/* Control panel                                                       */
/* ------------------------------------------------------------------ */

.control-panel {
  display: flex;
  flex-direction: column;
  gap: 11px;
  min-height: 0;
  padding: 17px;
  overflow: auto;
  background:
    linear-gradient(160deg, rgba(13, 27, 53, 0.62), transparent 45%),
    var(--panel);
  border: 1px solid var(--stroke);
  border-radius: 22px;
  scrollbar-width: none;
}

.control-panel::-webkit-scrollbar {
  display: none;
}

.panel-label {
  color: var(--dim);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
}

.turn-card {
  padding: 13px 15px 14px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--turn-color) 10%, transparent), rgba(5, 11, 23, 0.2));
  border: 1px solid color-mix(in srgb, var(--turn-color) 21%, transparent);
  border-radius: 14px;
  transition: background 250ms ease, border-color 250ms ease;
}

.turn-name {
  margin-top: 3px;
  color: var(--turn-color);
  font-family: var(--mono);
  font-size: 30px;
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: 0.06em;
  text-shadow: 0 0 24px color-mix(in srgb, var(--turn-color) 55%, transparent);
  transition: color 250ms ease, text-shadow 250ms ease;
}

.turn-sub {
  margin-top: 4px;
  color: #8ca3c5;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.05em;
}

.turn-bar {
  height: 2px;
  margin-top: 12px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 2px;
}

.turn-bar span {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, var(--turn-color));
  border-radius: 2px;
  transform-origin: left center;
  animation: barSlide 2.8s ease-in-out infinite;
}

@keyframes barSlide {
  0%, 100% { opacity: 0.25; transform: scaleX(0.55); }
  50% { opacity: 1; transform: scaleX(1); }
}

.selected-info {
  min-height: 74px;
  padding: 11px 13px;
  background: rgba(4, 10, 22, 0.55);
  border: 1px solid rgba(101, 159, 230, 0.12);
  border-radius: 12px;
}

.selected-info .panel-label {
  color: #6e85a8;
}

.selected-info.active .panel-label {
  color: var(--turn-soft);
}

.info-text {
  margin-top: 6px;
  color: #b9cbe6;
  font-size: 12px;
  line-height: 1.45;
}

.actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.action-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 54px;
  overflow: hidden;
  cursor: pointer;
  border-radius: 12px;
  transition: transform 130ms ease, filter 160ms ease, opacity 160ms ease, border-color 160ms ease, background 160ms ease;
}

.action-btn:active:not(:disabled) {
  transform: translateY(1px) scale(0.995);
}

.action-btn:disabled {
  cursor: default;
  opacity: 0.4;
  filter: saturate(0.35);
}

.rotate-btn {
  gap: 10px;
  color: #bed4f0;
  background: linear-gradient(180deg, rgba(25, 45, 79, 0.72), rgba(10, 20, 38, 0.8));
  border: 1px solid rgba(112, 176, 255, 0.25);
}

.rotate-btn:hover:not(:disabled) {
  background: linear-gradient(180deg, rgba(34, 61, 105, 0.85), rgba(13, 27, 51, 0.9));
  border-color: rgba(112, 176, 255, 0.5);
}

.action-icon {
  font-size: 22px;
  line-height: 1;
  transition: transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.rotate-btn:hover:not(:disabled) .action-icon {
  transform: rotate(90deg);
}

.action-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1.1;
}

.action-label {
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.16em;
}

.action-hint {
  margin-top: 3px;
  color: #6f87aa;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.fire-btn {
  min-height: 76px;
  color: #fff;
  background:
    linear-gradient(140deg, color-mix(in srgb, var(--turn-color) 78%, #fff 5%), color-mix(in srgb, var(--turn-color) 38%, #071020) 62%, #071020);
  border: 1px solid color-mix(in srgb, var(--turn-color) 72%, transparent);
  box-shadow:
    0 8px 30px color-mix(in srgb, var(--turn-color) 17%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.fire-btn:hover:not(:disabled) {
  filter: brightness(1.15);
  box-shadow:
    0 10px 38px color-mix(in srgb, var(--turn-color) 30%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.24);
}

.fire-btn.ready:not(:disabled) {
  animation: fireBreathe 1.9s ease-in-out infinite;
}

@keyframes fireBreathe {
  0%, 100% { box-shadow: 0 8px 28px color-mix(in srgb, var(--turn-color) 14%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.16); }
  50% { box-shadow: 0 8px 44px color-mix(in srgb, var(--turn-color) 36%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.25); }
}

.fire-glow {
  position: absolute;
  top: -65%;
  left: 50%;
  width: 65%;
  height: 170%;
  pointer-events: none;
  background: radial-gradient(ellipse, rgba(255, 255, 255, 0.28), transparent 68%);
  filter: blur(8px);
  transform: translateX(-50%);
}

.fire-copy {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.fire-label {
  font-family: var(--mono);
  font-size: 23px;
  font-weight: 800;
  letter-spacing: 0.24em;
  text-indent: 0.24em;
  line-height: 1.05;
  text-shadow: 0 0 18px rgba(255, 255, 255, 0.32);
}

.fire-sub {
  margin-top: 4px;
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
  opacity: 0.72;
}

kbd {
  display: inline-block;
  padding: 1px 4px;
