.overlay {
  position: fixed;
  z-index: 50;
  inset: 0;
  display: grid;
  place-items: center;
  padding:
    max(16px, env(safe-area-inset-top))
    max(16px, env(safe-area-inset-right))
    max(16px, env(safe-area-inset-bottom))
    max(16px, env(safe-area-inset-left));
  overflow: auto;
  background:
    radial-gradient(ellipse 50% 55% at 50% 48%, rgba(16, 40, 82, 0.3), transparent 70%),
    rgba(2, 5, 12, 0.82);
  -webkit-backdrop-filter: blur(7px);
  backdrop-filter: blur(7px);
  animation: overlayIn 300ms ease both;
}

@keyframes overlayIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.menu-card,
.gameover-card {
  position: relative;
  width: min(548px, 100%);
  margin: auto;
  padding: clamp(24px, 4vw, 40px);
  overflow: hidden;
  background:
    linear-gradient(155deg, rgba(22, 42, 79, 0.68), transparent 42%),
