test('beam follows multiple reflections and stops at the wall', () => {
  const state = customState([
    // Emitter sits inside the loop and fires into mirror D.
    emitter(3, 2, 1),
    mirror(4, 2, 3, 'blue', 'd'),
    mirror(4, 4, 0, 'blue', 'c'),
    mirror(2, 4, 1, 'blue', 'b'),
    mirror(2, 2, 2, 'blue', 'a'),
    king(7, 7, 'red'),
    king(0, 0, 'blue'),
  ]);
  const shot = traceLaser(state, 'red');
  // The four mirrors form a closed loop, which is detected and terminated.
  assert.equal(shot.endReason, 'loop');
  assert.equal(endOf(shot).kind, 'loop');
  const reflections = shot.events.filter((event) => event.kind === 'reflect');
  assert.ok(reflections.length >= 4);
});

input.newString:
test('beam follows a closed mirror circuit and terminates instead of looping forever', () => {
  const state = customState([
    // Emitter is on the circuit edge; its beam joins a four-mirror circuit and
    // returns to the emitter, where it is safely absorbed after four reflections.
    emitter(4, 2, 1),
    mirror(5, 2, 3, 'blue', 'd'),
    mirror(5, 4, 0, 'blue', 'c'),
    mirror(3, 4, 1, 'blue', 'b'),
    mirror(3, 2, 2, 'blue', 'a'),
    king(7, 7, 'red'),
    king(0, 0, 'blue'),
  ]);
  const shot = traceLaser(state, 'red');
  assert.equal(shot.endReason, 'emitter');
  assert.equal(endOf(shot).kind, 'absorb');
  const reflections = shot.events.filter((event) => event.kind === 'reflect');
  assert.equal(reflections.length, 4);
  assert.ok(shot.points.length < 256);
});

